'use client';

import { useCallback, useEffect, useMemo, useState, type FormEvent, type ReactNode } from 'react';
import { useRouter } from 'next/navigation';
import { Activity, ArrowRight, BookOpen, Check, ChevronDown, CircleAlert, ClipboardCheck, FileText, GraduationCap, Layers3, LayoutDashboard, LibraryBig, LogOut, Menu, MessageSquareText, Plus, RefreshCw, Save, Search, Send, Sparkles, UploadCloud, Video, X, type LucideIcon } from 'lucide-react';

const API = (process.env.NEXT_PUBLIC_API_URL || 'https://learnora-backend.vercel.app').replace(/\/$/, '');
type User = { name?: string; email?: string; role?: string };
type Course = { id: string; title: string; slug?: string; short_description?: string; description?: string; level?: string; status?: string; ownership?: string; organisation_id?: string | null; estimated_hours?: number; created_at?: string; settings?: { track?: string; topics?: string[] } };
type Lesson = { id: string; module_id: string; title: string; slug?: string; description?: string; order_index?: number; lesson_type?: string; content?: string; duration_minutes?: number; is_preview?: boolean; status?: string };
type Module = { id: string; course_id: string; title: string; description?: string; order_index?: number; status?: string; lessons: Lesson[] };
type VideoRecord = { id: string; provider?: string; title?: string; external_video_id?: string; status?: string };
type ResourceRecord = { id: string; title: string; resource_type?: string; external_url?: string; storage_path?: string };
type Cohort = { id: string; name: string; description?: string; status?: string; start_date?: string; end_date?: string; capacity?: number };
type CohortMember = { id?: string; user_id?: string; name?: string; full_name?: string; email?: string; status?: string; role?: string };
type Tab = 'overview' | 'courses' | 'curriculum' | 'cohorts' | 'review' | 'ai' | 'creator';
type Notice = { kind: 'success' | 'error'; text: string };
const nav: { id: Tab; label: string; icon: LucideIcon; group: string }[] = [
  { id: 'overview', label: 'Overview', icon: LayoutDashboard, group: 'Teaching' },
  { id: 'courses', label: 'My courses', icon: LibraryBig, group: 'Teaching' },
  { id: 'curriculum', label: 'Curriculum studio', icon: Layers3, group: 'Teaching' },
  { id: 'cohorts', label: 'Cohorts & learners', icon: UsersRound, group: 'Teaching' },
  { id: 'review', label: 'Learner review', icon: ClipboardCheck, group: 'Teaching' },
  { id: 'ai', label: 'AI teaching assistant', icon: Sparkles, group: 'Tools' },
  { id: 'creator', label: 'Creator studio', icon: GraduationCap, group: 'Tools' },
];
const inputClass = 'w-full rounded-lg border border-white/10 bg-[#080b0f] px-3 py-2.5 text-sm text-white outline-none placeholder:text-slate-600 focus:border-[#d7ad35]/50';
const buttonClass = 'inline-flex items-center justify-center gap-2 rounded-lg bg-[#d7ad35] px-4 py-2.5 text-xs font-bold text-[#111827] hover:bg-[#f2d477] disabled:cursor-not-allowed disabled:opacity-50';
async function api<T = any>(path: string, token: string, init: RequestInit = {}): Promise<T> {
  const organisationId = typeof window !== 'undefined' ? (localStorage.getItem('phx_organisation_id') || localStorage.getItem('phx_organization_id') || localStorage.getItem('phx_org_id') || '') : '';
  const response = await fetch(API + path, { ...init, cache: 'no-store', headers: { Accept: 'application/json', Authorization: 'Bearer ' + token, ...(organisationId ? { 'X-Organisation-ID': organisationId } : {}), ...(init.body ? { 'Content-Type': 'application/json' } : {}), ...(init.headers || {}) } });
  const body = await response.json().catch(() => ({}));
  if (!response.ok) throw new Error(typeof body.detail === 'string' ? body.detail : typeof body.error === 'string' ? body.error : 'The request could not be completed.');
  return body as T;
}
function rows<T>(body: any, key: string): T[] { return Array.isArray(body) ? body : Array.isArray(body?.[key]) ? body[key] : []; }
function slugify(value: string) { return value.trim().toLowerCase().normalize('NFKD').replace(/[\u0300-\u036f]/g, '').replace(/[^a-z0-9]+/g, '-').replace(/^-|-$/g, '').slice(0, 190); }
function dateLabel(value?: string) { if (!value) return 'Date unavailable'; const d = new Date(value); return Number.isNaN(d.getTime()) ? 'Date unavailable' : d.toLocaleDateString(undefined, { day: 'numeric', month: 'short', year: 'numeric' }); }
function Field({ label, children }: { label: string; children: ReactNode }) { return <label className="block text-xs font-medium text-slate-300">{label}<div className="mt-2">{children}</div></label>; }
function Status({ value }: { value?: string }) { const v = (value || 'unknown').toLowerCase(); const tone = v === 'published' || v === 'active' ? 'border-emerald-400/20 bg-emerald-400/10 text-emerald-200' : v === 'archived' ? 'border-slate-500/20 bg-slate-500/10 text-slate-400' : 'border-amber-300/20 bg-amber-300/10 text-amber-100'; return <span className={'inline-flex rounded-full border px-2.5 py-1 text-[10px] font-semibold capitalize ' + tone}>{v.replace(/_/g, ' ')}</span>; }
function Heading({ eyebrow, title, detail, action, onAction }: { eyebrow: string; title: string; detail: string; action?: string; onAction?: () => void }) { return <div className="mb-7 flex flex-col gap-4 sm:flex-row sm:items-end sm:justify-between"><div><p className="text-[10px] font-bold uppercase tracking-[.17em] text-[#f2d477]">{eyebrow}</p><h1 className="mt-2 font-serif text-3xl tracking-tight text-white sm:text-4xl">{title}</h1><p className="mt-3 max-w-2xl text-sm leading-6 text-slate-400">{detail}</p></div>{action && onAction && <button onClick={onAction} className="inline-flex w-fit items-center gap-2 border border-white/10 px-4 py-2.5 text-xs font-semibold text-slate-200 hover:border-[#d7ad35]/50 hover:text-[#f2d477]">{action}<ArrowRight size={14}/></button>}</div>; }
function Empty({ icon: Icon, title, detail, action, onAction }: { icon: LucideIcon; title: string; detail: string; action?: string; onAction?: () => void }) { return <div className="rounded-2xl border border-white/[.09] bg-[#0e1319] p-7 sm:p-9"><span className="grid size-12 place-items-center rounded-xl border border-[#d7ad35]/20 bg-[#d7ad35]/10 text-[#f2d477]"><Icon size={21}/></span><h3 className="mt-4 text-base font-semibold text-white">{title}</h3><p className="mt-2 max-w-2xl text-sm leading-6 text-slate-400">{detail}</p>{action && onAction && <button onClick={onAction} className={buttonClass + ' mt-5'}>{action}<ArrowRight size={14}/></button>}</div>; }

export default function InstructorWorkspace() {
  const router = useRouter();
  const [token, setToken] = useState('');
  const [user, setUser] = useState<User>({});
  const [organisationId, setOrganisationId] = useState('');
  const [authLoading, setAuthLoading] = useState(true);
  const [tab, setTab] = useState<Tab>('overview');
  const [mobileOpen, setMobileOpen] = useState(false);
  const [loading, setLoading] = useState(false);
  const [courses, setCourses] = useState<Course[]>([]);
  const [cohorts, setCohorts] = useState<Cohort[]>([]);
  const [cohortMembers, setCohortMembers] = useState<CohortMember[]>([]);
  const [selectedCohortId, setSelectedCohortId] = useState('');
  const [showCohortForm, setShowCohortForm] = useState(false);
  const [cohortForm, setCohortForm] = useState({ name: '', description: '', start_date: '', end_date: '', capacity: '' });
  const [selectedCourseId, setSelectedCourseId] = useState('');
  const [modules, setModules] = useState<Module[]>([]);
  const [selectedLessonId, setSelectedLessonId] = useState('');
  const [newLessonModuleId, setNewLessonModuleId] = useState('');
  const [videos, setVideos] = useState<VideoRecord[]>([]);
  const [resources, setResources] = useState<ResourceRecord[]>([]);
  const [search, setSearch] = useState('');
  const [notice, setNotice] = useState<Notice | null>(null);
  const [busy, setBusy] = useState(false);
  const [showCourseForm, setShowCourseForm] = useState(false);
  const [showModuleForm, setShowModuleForm] = useState(false);
  const [showLessonForm, setShowLessonForm] = useState(false);
  const [courseForm, setCourseForm] = useState({ title: '', short_description: '', description: '', level: 'beginner', track: '', estimated_hours: '4' });
  const [moduleForm, setModuleForm] = useState({ title: '', description: '' });
  const [lessonForm, setLessonForm] = useState({ title: '', description: '', lesson_type: 'article', content: '', duration_minutes: '10', status: 'draft' });
  const [resourceForm, setResourceForm] = useState({ title: '', external_url: '', resource_type: 'link' });
  const [videoForm, setVideoForm] = useState({ title: '', provider: 'youtube', external_video_id: '' });
  const [aiPrompt, setAiPrompt] = useState('');
  const [aiOutput, setAiOutput] = useState('');
  const [aiBusy, setAiBusy] = useState(false);
  const [aiMode, setAiMode] = useState<'instructor' | 'content_generation'>('instructor');

  const selectedCourse = useMemo(() => courses.find(c => c.id === selectedCourseId) || null, [courses, selectedCourseId]);
  const selectedCohort = useMemo(() => cohorts.find(c => c.id === selectedCohortId) || null, [cohorts, selectedCohortId]);
  const selectedLesson = useMemo(() => modules.flatMap(m => m.lessons || []).find(l => l.id === selectedLessonId) || null, [modules, selectedLessonId]);
  const selectedLessonModule = useMemo(() => modules.find(m => m.lessons.some(l => l.id === selectedLessonId)) || modules[0] || null, [modules, selectedLessonId]);
  const targetModule = useMemo(() => modules.find(m => m.id === newLessonModuleId) || selectedLessonModule, [modules, newLessonModuleId, selectedLessonModule]);
  const visibleCourses = useMemo(() => courses.filter(c => !search.trim() || [c.title, c.short_description, c.settings?.track, c.status].some(v => String(v || '').toLowerCase().includes(search.trim().toLowerCase()))), [courses, search]);
  const publishedCount = courses.filter(c => c.status === 'published').length;
  const draftCount = courses.filter(c => c.status === 'draft').length;
  const lessonCount = modules.reduce((n, m) => n + m.lessons.filter(l => l.status !== 'archived').length, 0);
  const readyLessons = modules.reduce((n, m) => n + m.lessons.filter(l => l.status === 'published').length, 0);

  const loadCourses = useCallback(async (authToken: string) => {
    setLoading(true);
    try {
      const body = await api<any>('/api/courses', authToken);
      const result = rows<Course>(body, 'courses');
      setCourses(result);
      setSelectedCourseId(current => current && result.some(c => c.id === current) ? current : result[0]?.id || '');
      setNotice(null);
    } catch (error) {
      setCourses([]);
      setNotice({ kind: 'error', text: error instanceof Error ? error.message : 'Courses could not be loaded. Check your instructor permissions.' });
    } finally { setLoading(false); }
  }, []);

  const loadCohorts = useCallback(async (authToken: string, orgId: string) => {
    if (!orgId) { setCohorts([]); setCohortMembers([]); setSelectedCohortId(''); return; }
    try {
      const body = await api<any>('/api/organisations/' + encodeURIComponent(orgId) + '/cohorts', authToken);
      const result = rows<Cohort>(body, 'cohorts');
      setCohorts(result);
      setSelectedCohortId(current => current && result.some(c => c.id === current) ? current : result[0]?.id || '');
    } catch (error) {
      setCohorts([]); setCohortMembers([]);
      setNotice({ kind: 'error', text: error instanceof Error ? error.message : 'Cohorts could not be loaded for this organisation.' });
    }
  }, []);

  const loadCohortMembers = useCallback(async (authToken: string, orgId: string, cohortId: string) => {
    if (!orgId || !cohortId) { setCohortMembers([]); return; }
    try {
      const body = await api<any>('/api/organisations/' + encodeURIComponent(orgId) + '/cohorts/' + encodeURIComponent(cohortId) + '/members', authToken);
      setCohortMembers(rows<CohortMember>(body, 'members'));
    } catch (error) {
      setCohortMembers([]);
      setNotice({ kind: 'error', text: error instanceof Error ? error.message : 'Learner memberships could not be loaded.' });
    }
  }, []);

  const loadStructure = useCallback(async (authToken: string, courseId: string) => {
    if (!courseId) { setModules([]); setSelectedLessonId(''); return; }
    try {
      const body = await api<any>('/api/course-content/courses/' + encodeURIComponent(courseId) + '/structure', authToken);
      const result = rows<Module>(body, 'modules').map(m => ({ ...m, lessons: rows<Lesson>(m, 'lessons') }));
      setModules(result);
      setSelectedLessonId(current => current && result.some(m => m.lessons.some(l => l.id === current)) ? current : result.flatMap(m => m.lessons)[0]?.id || '');
      setNewLessonModuleId(current => current && result.some(m => m.id === current) ? current : result[0]?.id || '');
    } catch (error) {
      setModules([]);
      setNotice({ kind: 'error', text: error instanceof Error ? error.message : 'Course curriculum could not be loaded.' });
    }
  }, []);

  const loadMedia = useCallback(async (authToken: string, lessonId: string) => {
    if (!lessonId) { setVideos([]); setResources([]); return; }
    try {
      const body = await api<any>('/api/media/lessons/' + encodeURIComponent(lessonId), authToken);
      setVideos(rows<VideoRecord>(body, 'videos')); setResources(rows<ResourceRecord>(body, 'resources'));
    } catch { setVideos([]); setResources([]); }
  }, []);

  useEffect(() => {
    const stored = localStorage.getItem('phx_token') || '';
    if (!stored) { router.replace('/login'); return; }
    setToken(stored);
    setUser({ name: localStorage.getItem('phx_name') || '', email: localStorage.getItem('phx_email') || '', role: localStorage.getItem('phx_role') || '' });
    setOrganisationId(localStorage.getItem('phx_organisation_id') || localStorage.getItem('phx_organization_id') || localStorage.getItem('phx_org_id') || '');
    setAuthLoading(false);
    void loadCourses(stored);
    const orgId = localStorage.getItem('phx_organisation_id') || localStorage.getItem('phx_organization_id') || localStorage.getItem('phx_org_id') || '';
    if (orgId) void loadCohorts(stored, orgId);
  }, [router, loadCourses, loadCohorts]);
  useEffect(() => { if (token && selectedCourseId) void loadStructure(token, selectedCourseId); else setModules([]); }, [token, selectedCourseId, loadStructure]);
  useEffect(() => { if (token && organisationId && selectedCohortId) void loadCohortMembers(token, organisationId, selectedCohortId); else setCohortMembers([]); }, [token, organisationId, selectedCohortId, loadCohortMembers]);
  useEffect(() => { if (token && selectedLessonId) void loadMedia(token, selectedLessonId); else { setVideos([]); setResources([]); } }, [token, selectedLessonId, loadMedia]);

  const refresh = () => { if (token) void loadCourses(token); if (token && selectedCourseId) void loadStructure(token, selectedCourseId); };
  const logout = () => { ['phx_token', 'phx_email', 'phx_role', 'phx_plan', 'phx_name', 'phx_account_type', 'phx_last_course_id', 'phx_trial_started_at'].forEach(k => localStorage.removeItem(k)); router.replace('/login'); };
  const createCourse = async (event: FormEvent) => {
    event.preventDefault(); if (!token || !courseForm.title.trim()) return; setBusy(true); setNotice(null);
    try {
      const platformRole = ['super_admin', 'staff_admin', 'admin', 'owner'].includes(String(user.role || '').toLowerCase());
      if (!organisationId && !platformRole) throw new Error('The current backend requires an organisation context for instructor course authoring. Ask your organisation administrator to connect this workspace, or have independent creator authoring enabled for your account.');
      const ownership = organisationId ? 'organisation' : 'learnora';
      const payload = { title: courseForm.title.trim(), slug: slugify(courseForm.title), short_description: courseForm.short_description.trim(), description: courseForm.description.trim(), level: courseForm.level, track: courseForm.track.trim() || null, estimated_hours: Number(courseForm.estimated_hours) || null, status: 'draft', ownership, ...(organisationId ? { organisation_id: organisationId } : {}) };
      const body = await api<any>('/api/courses', token, { method: 'POST', body: JSON.stringify(payload) });
      const course = body.course as Course;
      setCourses(current => [course, ...current.filter(c => c.id !== course.id)]); setSelectedCourseId(course.id); setShowCourseForm(false); setCourseForm({ title: '', short_description: '', description: '', level: 'beginner', track: '', estimated_hours: '4' }); setTab('curriculum');
      setNotice({ kind: 'success', text: 'Course draft created. Add a module and lessons before publishing.' });
    } catch (error) { setNotice({ kind: 'error', text: error instanceof Error ? error.message : 'Course creation failed. Your account may not have creator permissions.' }); }
    finally { setBusy(false); }
  };
  const createCohort = async (event: FormEvent) => {
    event.preventDefault();
    if (!token || !organisationId || !cohortForm.name.trim()) return;
    setBusy(true);
    try {
      const body = await api<any>('/api/organisations/' + encodeURIComponent(organisationId) + '/cohorts', token, { method: 'POST', body: JSON.stringify({ name: cohortForm.name.trim(), description: cohortForm.description.trim(), start_date: cohortForm.start_date || null, end_date: cohortForm.end_date || null, capacity: cohortForm.capacity ? Number(cohortForm.capacity) : null, status: 'upcoming' }) });
      const cohort = body.cohort as Cohort;
      setCohorts(current => [cohort, ...current.filter(c => c.id !== cohort.id)]);
      setSelectedCohortId(cohort.id); setShowCohortForm(false); setCohortForm({ name: '', description: '', start_date: '', end_date: '', capacity: '' });
      setNotice({ kind: 'success', text: 'Cohort created.' });
    } catch (error) { setNotice({ kind: 'error', text: error instanceof Error ? error.message : 'Cohort creation failed. Your role may not have organisation-update permission.' }); }
    finally { setBusy(false); }
  };
  const createModule = async (event: FormEvent) => {
    event.preventDefault(); if (!token || !selectedCourse || !moduleForm.title.trim()) return; setBusy(true);
    try {
      await api('/api/course-content/courses/' + encodeURIComponent(selectedCourse.id) + '/modules', token, { method: 'POST', body: JSON.stringify({ title: moduleForm.title.trim(), description: moduleForm.description.trim(), order_index: modules.length, status: 'draft' }) });
      setModuleForm({ title: '', description: '' }); setShowModuleForm(false); await loadStructure(token, selectedCourse.id); setNotice({ kind: 'success', text: 'Module added to the course curriculum.' });
    } catch (error) { setNotice({ kind: 'error', text: error instanceof Error ? error.message : 'Module could not be created.' }); }
    finally { setBusy(false); }
  };
  const createLesson = async (event: FormEvent) => {
    event.preventDefault(); if (!token || !selectedCourse || !targetModule || !lessonForm.title.trim()) return; setBusy(true);
    try {
      await api('/api/course-content/modules/' + encodeURIComponent(targetModule.id) + '/lessons', token, { method: 'POST', body: JSON.stringify({ title: lessonForm.title.trim(), slug: slugify(lessonForm.title), description: lessonForm.description.trim(), order_index: targetModule.lessons.length, lesson_type: lessonForm.lesson_type, content: lessonForm.content, duration_minutes: Number(lessonForm.duration_minutes) || 0, status: lessonForm.status, is_preview: false }) });
      setLessonForm({ title: '', description: '', lesson_type: 'article', content: '', duration_minutes: '10', status: 'draft' }); setShowLessonForm(false); await loadStructure(token, selectedCourse.id); setNotice({ kind: 'success', text: 'Lesson saved to the selected module.' });
    } catch (error) { setNotice({ kind: 'error', text: error instanceof Error ? error.message : 'Lesson could not be created.' }); }
    finally { setBusy(false); }
  };
  const saveLesson = async (event: FormEvent) => {
    event.preventDefault(); if (!token || !selectedLesson) return; setBusy(true);
    try {
      await api('/api/course-content/lessons/' + encodeURIComponent(selectedLesson.id), token, { method: 'PATCH', body: JSON.stringify({ title: selectedLesson.title, description: selectedLesson.description || '', lesson_type: selectedLesson.lesson_type || 'article', content: selectedLesson.content || '', duration_minutes: Number(selectedLesson.duration_minutes) || 0, status: selectedLesson.status || 'draft' }) });
      await loadStructure(token, selectedCourseId); setNotice({ kind: 'success', text: 'Lesson changes saved.' });
    } catch (error) { setNotice({ kind: 'error', text: error instanceof Error ? error.message : 'Lesson changes could not be saved.' }); }
    finally { setBusy(false); }
  };
  const publishCourse = async () => {
    if (!token || !selectedCourse) return; setBusy(true);
    try { const body = await api<any>('/api/courses/' + encodeURIComponent(selectedCourse.id) + '/publish', token, { method: 'POST' }); if (body.course) setCourses(current => current.map(c => c.id === selectedCourse.id ? body.course : c)); else await loadCourses(token); setNotice({ kind: 'success', text: 'Course publication request completed.' }); }
    catch (error) { setNotice({ kind: 'error', text: error instanceof Error ? error.message : 'Course could not be published. Check publication requirements and permissions.' }); }
    finally { setBusy(false); }
  };
  const addResource = async (event: FormEvent) => {
    event.preventDefault(); if (!token || !selectedLesson || !resourceForm.title.trim() || !resourceForm.external_url.trim()) return; setBusy(true);
    try { await api('/api/media/lessons/' + encodeURIComponent(selectedLesson.id) + '/resources', token, { method: 'POST', body: JSON.stringify({ title: resourceForm.title.trim(), resource_type: resourceForm.resource_type, external_url: resourceForm.external_url.trim() }) }); setResourceForm({ title: '', external_url: '', resource_type: 'link' }); await loadMedia(token, selectedLesson.id); setNotice({ kind: 'success', text: 'Resource attached to this lesson.' }); }
    catch (error) { setNotice({ kind: 'error', text: error instanceof Error ? error.message : 'Resource could not be attached.' }); }
    finally { setBusy(false); }
  };
  const addVideo = async (event: FormEvent) => {
    event.preventDefault(); if (!token || !selectedLesson || !videoForm.title.trim() || !videoForm.external_video_id.trim()) return; setBusy(true);
    try { await api('/api/media/lessons/' + encodeURIComponent(selectedLesson.id) + '/videos', token, { method: 'POST', body: JSON.stringify({ title: videoForm.title.trim(), provider: videoForm.provider, external_video_id: videoForm.external_video_id.trim(), status: 'pending', is_private: true }) }); setVideoForm({ title: '', provider: 'youtube', external_video_id: '' }); await loadMedia(token, selectedLesson.id); setNotice({ kind: 'success', text: 'Video metadata saved. Playback still depends on the provider integration.' }); }
    catch (error) { setNotice({ kind: 'error', text: error instanceof Error ? error.message : 'Video metadata could not be saved.' }); }
    finally { setBusy(false); }
  };
  const askAi = async (event: FormEvent) => {
    event.preventDefault(); if (!token || !aiPrompt.trim()) return; setAiBusy(true); setAiOutput('');
    try { const body = await api<any>('/api/ai/ask', token, { method: 'POST', body: JSON.stringify({ feature: aiMode, message: aiPrompt.trim() }) }); const answer = body.answer || body.response || body.message || body.output || body.content; setAiOutput(typeof answer === 'string' ? answer : JSON.stringify(body, null, 2)); }
    catch (error) { setNotice({ kind: 'error', text: error instanceof Error ? error.message : 'The AI teaching assistant is unavailable.' }); }
    finally { setAiBusy(false); }
  };
  const updateLesson = (patch: Partial<Lesson>) => { if (!selectedLesson) return; setModules(current => current.map(m => ({ ...m, lessons: m.lessons.map(l => l.id === selectedLesson.id ? { ...l, ...patch } : l) }))); };

  const overview = <div>
    <Heading eyebrow="Instructor workspace" title={'Welcome back' + (user.name ? ', ' + user.name.split(' ')[0] : '')} detail="Build clear learning journeys, keep course content healthy, and help learners demonstrate what they can do." action="Manage courses" onAction={() => setTab('courses')}/>
    <div className="grid gap-3 sm:grid-cols-2 xl:grid-cols-4">{[{label:'Courses in workspace',value:loading?'—':String(courses.length),icon:LibraryBig,hint:'Visible to your current permissions'},{label:'Published courses',value:loading?'—':String(publishedCount),icon:BookOpen,hint:'Live course records'},{label:'Draft courses',value:loading?'—':String(draftCount),icon:FileText,hint:'Still being prepared'},{label:'Lessons in selected course',value:selectedCourse?String(lessonCount):'—',icon:Layers3,hint:selectedCourse?.title || 'Choose a course to inspect'}].map(card=><div key={card.label} className="rounded-2xl border border-white/[.09] bg-[#0e1319] p-5"><div className="flex items-center justify-between gap-3"><span className="text-xs text-slate-400">{card.label}</span><card.icon size={17} className="text-[#f2d477]"/></div><p className="mt-4 text-3xl font-semibold tracking-tight text-white">{card.value}</p><p className="mt-2 text-[10px] leading-5 text-slate-500">{card.hint}</p></div>)}</div>
    <div className="mt-5 grid gap-5 xl:grid-cols-[minmax(0,1.2fr)_minmax(280px,.8fr)]"><section className="rounded-2xl border border-white/[.09] bg-[#0e1319] p-5 sm:p-6"><div className="flex items-center justify-between gap-3"><div><p className="text-[10px] uppercase tracking-[.15em] text-[#f2d477]">Curriculum health</p><h2 className="mt-2 text-base font-semibold text-white">Build a complete learning journey</h2></div><button onClick={()=>setTab('curriculum')} className="text-xs font-semibold text-[#f2d477]">Open studio <ArrowRight size={13} className="ml-1 inline"/></button></div>{selectedCourse?<><div className="mt-5 flex flex-wrap items-center justify-between gap-3"><div><p className="text-sm font-semibold text-white">{selectedCourse.title}</p><p className="mt-1 text-xs text-slate-500">{modules.length} modules · {lessonCount} lessons · {readyLessons} published lessons</p></div><Status value={selectedCourse.status}/></div><div className="mt-4 h-1.5 overflow-hidden rounded-full bg-white/10"><div className="h-full rounded-full bg-[#d7ad35]" style={{width:(lessonCount?Math.round(readyLessons/lessonCount*100):0)+'%'}}/></div><p className="mt-2 text-[10px] text-slate-500">{lessonCount?Math.round(readyLessons/lessonCount*100)+'% of lessons are marked published':'Add a module and lesson to begin.'}</p></>:<p className="mt-5 text-sm leading-6 text-slate-400">No course is selected. Create a draft if your account has creator permissions, or ask your organisation administrator to assign a course.</p>}</section>
      <section className="rounded-2xl border border-white/[.09] bg-[#0e1319] p-5 sm:p-6"><p className="text-[10px] uppercase tracking-[.15em] text-[#f2d477]">Quick actions</p><div className="mt-3 divide-y divide-white/[.07]">{[{label:'Create a course draft',detail:'Start with a clear outcome',icon:Plus,run:()=>{setShowCourseForm(true);setTab('courses');}},{label:'Write a lesson',detail:'Add content to a module',icon:FileText,run:()=>{setShowLessonForm(true);setTab('curriculum');}},{label:'Prepare an assessment',detail:'Draft a rubric or question set with AI',icon:Sparkles,run:()=>{setAiMode('content_generation');setAiPrompt('Draft a formative assessment aligned to a clear learning objective. Include instructions, marking criteria and an answer guide.');setTab('ai');}}].map(item=><button key={item.label} onClick={item.run} className="flex w-full items-center gap-3 py-4 text-left hover:bg-white/[.02]"><span className="grid size-9 place-items-center rounded-lg border border-white/10 text-[#f2d477]"><item.icon size={16}/></span><span className="min-w-0 flex-1"><span className="block text-xs font-semibold text-slate-200">{item.label}</span><span className="mt-1 block text-[10px] text-slate-500">{item.detail}</span></span><ArrowRight size={14} className="text-slate-600"/></button>)}</div></section></div>
    <section className="mt-5 rounded-2xl border border-white/[.09] bg-[#0e1319] p-5 sm:p-6"><div className="flex items-center justify-between gap-3"><div><p className="text-[10px] uppercase tracking-[.15em] text-[#f2d477]">Course records</p><h2 className="mt-2 text-base font-semibold text-white">Your courses</h2></div><button onClick={()=>setTab('courses')} className="text-xs font-semibold text-[#f2d477]">View all <ArrowRight size={13} className="ml-1 inline"/></button></div>{courses.length?<div className="mt-4 divide-y divide-white/[.07]">{courses.slice(0,5).map(c=><button key={c.id} onClick={()=>{setSelectedCourseId(c.id);setTab('curriculum');}} className="flex w-full items-center gap-3 py-4 text-left"><span className="grid size-10 shrink-0 place-items-center rounded-xl bg-white/[.04] text-[#f2d477]"><BookOpen size={17}/></span><span className="min-w-0 flex-1"><span className="block truncate text-sm font-medium text-slate-200">{c.title}</span><span className="mt-1 block text-[10px] text-slate-500">{c.settings?.track||'General learning'} · Created {dateLabel(c.created_at)}</span></span><Status value={c.status}/></button>)}</div>:<p className="mt-4 text-sm leading-6 text-slate-400">{notice?.text||'No course records are available for your current permissions.'}</p>}</section>
  </div>;

  const courseList = <div><Heading eyebrow="Course management" title="My courses" detail="Review courses visible to your account, inspect publication status, and continue building the curriculum." action="New course draft" onAction={()=>setShowCourseForm(true)}/>
    {showCourseForm&&<form onSubmit={createCourse} className="mb-5 rounded-2xl border border-[#d7ad35]/25 bg-[#0e1319] p-5 sm:p-6"><div className="mb-5 flex items-center justify-between"><div><h2 className="text-base font-semibold text-white">Create a course draft</h2><p className="mt-1 text-xs text-slate-500">The backend decides whether your account may create creator-owned courses.</p></div><button type="button" aria-label="Close form" onClick={()=>setShowCourseForm(false)} className="p-2 text-slate-500"><X size={16}/></button></div><div className="grid gap-4 md:grid-cols-2"><Field label="Course title"><input required maxLength={200} value={courseForm.title} onChange={e=>setCourseForm(s=>({...s,title:e.target.value}))} className={inputClass} placeholder="e.g. Data analysis foundations"/></Field><Field label="Learning track"><input maxLength={120} value={courseForm.track} onChange={e=>setCourseForm(s=>({...s,track:e.target.value}))} className={inputClass} placeholder="e.g. Data Science"/></Field><Field label="Short description"><input value={courseForm.short_description} onChange={e=>setCourseForm(s=>({...s,short_description:e.target.value}))} className={inputClass} placeholder="What will learners be able to do?"/></Field><Field label="Level"><select value={courseForm.level} onChange={e=>setCourseForm(s=>({...s,level:e.target.value}))} className={inputClass}><option value="beginner">Beginner</option><option value="intermediate">Intermediate</option><option value="advanced">Advanced</option><option value="mixed">Mixed</option></select></Field><Field label="Estimated learning hours"><input type="number" min="0" step="0.5" value={courseForm.estimated_hours} onChange={e=>setCourseForm(s=>({...s,estimated_hours:e.target.value}))} className={inputClass}/></Field><div className="md:col-span-2"><Field label="Course description"><textarea rows={3} value={courseForm.description} onChange={e=>setCourseForm(s=>({...s,description:e.target.value}))} className={inputClass} placeholder="Describe learning outcomes, curriculum and practical work."/></Field></div></div><div className="mt-5 flex justify-end gap-3"><button type="button" onClick={()=>setShowCourseForm(false)} className="border border-white/10 px-4 py-2.5 text-xs text-slate-300">Cancel</button><button disabled={busy} className={buttonClass}>{busy?'Creating…':'Create draft'}<Plus size={14}/></button></div></form>}
    <div className="mb-4 flex flex-col gap-3 sm:flex-row"><label className="flex flex-1 items-center gap-2 rounded-lg border border-white/10 bg-[#0e1319] px-3"><Search size={14} className="text-slate-500"/><input value={search} onChange={e=>setSearch(e.target.value)} placeholder="Search by title, track or status…" className="w-full bg-transparent py-3 text-xs text-white outline-none placeholder:text-slate-600"/></label><button onClick={refresh} disabled={loading} className="inline-flex items-center justify-center gap-2 border border-white/10 px-4 py-2.5 text-xs text-slate-300"><RefreshCw size={14}/>{loading?'Refreshing…':'Refresh'}</button></div>
    {visibleCourses.length?<div className="overflow-hidden rounded-2xl border border-white/[.09] bg-[#0e1319]"><div className="hidden grid-cols-[minmax(0,1fr)_120px_130px_140px] gap-4 border-b border-white/[.08] px-5 py-3 text-[10px] font-bold uppercase tracking-[.13em] text-slate-500 md:grid"><span>Course</span><span>Ownership</span><span>Status</span><span>Action</span></div>{visibleCourses.map(c=><div key={c.id} className="grid gap-3 border-b border-white/[.06] p-4 last:border-0 md:grid-cols-[minmax(0,1fr)_120px_130px_140px] md:items-center md:gap-4 md:px-5"><div className="min-w-0"><p className="truncate text-sm font-semibold text-white">{c.title}</p><p className="mt-1 line-clamp-2 text-xs leading-5 text-slate-500">{c.short_description||c.description||'No course description recorded.'}</p><p className="mt-1 text-[10px] text-slate-600">{c.settings?.track||'General learning'} · {c.estimated_hours?c.estimated_hours+' hours':'Duration not set'}</p></div><span className="text-xs capitalize text-slate-400">{c.ownership||'unknown'}</span><div><Status value={c.status}/></div><button onClick={()=>{setSelectedCourseId(c.id);setTab('curriculum');}} className="inline-flex items-center gap-1 text-xs font-semibold text-[#f2d477]">Edit curriculum <ArrowRight size={13}/></button></div>)}</div>:<Empty icon={LibraryBig} title={courses.length?'No matching courses':'No accessible courses yet'} detail={courses.length?'Try another search term.':notice?.text||'No course records were returned for your current permissions. An organisation administrator may need to assign courses, or independent creator access may need approval.'} action={courses.length?'Clear search':undefined} onAction={courses.length?()=>setSearch(''):undefined}/>}
  </div>;

  const curriculum = <div><Heading eyebrow="Authoring workspace" title="Curriculum studio" detail="Create modules and lessons, edit learning content, attach resources, and check publication readiness." action="Add module" onAction={()=>setShowModuleForm(true)}/>
    {courses.length>0&&<div className="mb-5 flex flex-col gap-3 rounded-xl border border-white/[.09] bg-[#0e1319] p-4 sm:flex-row sm:items-center"><Field label="Selected course"><select value={selectedCourseId} onChange={e=>setSelectedCourseId(e.target.value)} className={inputClass}>{courses.map(c=><option key={c.id} value={c.id}>{c.title}</option>)}</select></Field>{selectedCourse&&<div className="flex items-center gap-2"><Status value={selectedCourse.status}/><button disabled={busy||selectedCourse.status==='published'} onClick={publishCourse} className={buttonClass}>Publish course <ArrowRight size={14}/></button></div>}</div>}
    {showModuleForm&&selectedCourse&&<form onSubmit={createModule} className="mb-5 rounded-xl border border-[#d7ad35]/25 bg-[#0e1319] p-4"><div className="grid gap-3 sm:grid-cols-2"><Field label="Module title"><input required value={moduleForm.title} onChange={e=>setModuleForm(s=>({...s,title:e.target.value}))} className={inputClass}/></Field><Field label="Description"><input value={moduleForm.description} onChange={e=>setModuleForm(s=>({...s,description:e.target.value}))} className={inputClass}/></Field></div><div className="mt-3 flex justify-end gap-2"><button type="button" onClick={()=>setShowModuleForm(false)} className="border border-white/10 px-3 py-2 text-xs text-slate-300">Cancel</button><button disabled={busy} className={buttonClass}>Add module <Plus size={13}/></button></div></form>}
    {!selectedCourse?<Empty icon={Layers3} title="Choose a course to begin" detail="Courses appear here only when the backend returns them for your current permissions." action="Go to my courses" onAction={()=>setTab('courses')}/>:<div className="grid gap-5 xl:grid-cols-[minmax(250px,.72fr)_minmax(0,1.28fr)]">
      <section className="h-fit rounded-2xl border border-white/[.09] bg-[#0e1319] p-4"><div className="flex items-start justify-between gap-3"><div><p className="text-[10px] uppercase tracking-[.14em] text-[#f2d477]">Course structure</p><h2 className="mt-2 text-sm font-semibold text-white">{selectedCourse.title}</h2><p className="mt-1 text-[10px] text-slate-500">{modules.length} modules · {lessonCount} lessons</p></div><button aria-label="Add lesson" onClick={()=>{setShowLessonForm(true);setNewLessonModuleId(selectedLessonModule?.id||modules[0]?.id||'');}} className="rounded-lg border border-white/10 p-2 text-[#f2d477]"><Plus size={15}/></button></div>
        <div className="mt-4 space-y-3">{modules.map((m,index)=><div key={m.id} className="rounded-xl border border-white/[.08] p-3"><div className="flex items-start gap-2"><span className="grid size-7 shrink-0 place-items-center rounded-lg bg-white/[.05] text-[10px] text-slate-400">{index+1}</span><div className="min-w-0 flex-1"><p className="text-xs font-semibold text-slate-200">{m.title}</p><p className="mt-1 text-[10px] text-slate-500">{m.lessons.length} lessons · {m.status||'status unavailable'}</p></div><button aria-label={'Add lesson to '+m.title} onClick={()=>{setNewLessonModuleId(m.id);setShowLessonForm(true);}} className="p-1.5 text-[#f2d477]"><Plus size={14}/></button></div><div className="mt-2 space-y-1">{m.lessons.map(l=><button key={l.id} onClick={()=>{setSelectedLessonId(l.id);setShowLessonForm(false);}} className={'flex w-full items-center gap-2 rounded-lg px-2.5 py-2 text-left '+(l.id===selectedLessonId?'bg-[#d7ad35]/10 text-[#f2d477]':'text-slate-400 hover:bg-white/[.04]')}><FileText size={13}/><span className="min-w-0 flex-1 truncate text-[11px]">{l.title}</span><span className="text-[9px] capitalize">{l.status||'—'}</span></button>)}</div></div>)}</div>
        {!modules.length&&<p className="py-7 text-center text-xs leading-5 text-slate-500">No modules in this course yet. Add the first module to start the curriculum.</p>}
      </section>
      <section className="space-y-5">
        {showLessonForm?<form onSubmit={createLesson} className="rounded-2xl border border-white/[.09] bg-[#0e1319] p-5"><p className="text-[10px] uppercase tracking-[.14em] text-[#f2d477]">New lesson</p><h2 className="mt-2 text-base font-semibold text-white">Add to curriculum</h2><div className="mt-4 space-y-4"><Field label="Target module"><select value={newLessonModuleId} onChange={e=>setNewLessonModuleId(e.target.value)} className={inputClass}>{modules.map(m=><option key={m.id} value={m.id}>{m.title}</option>)}</select></Field><Field label="Lesson title"><input required value={lessonForm.title} onChange={e=>setLessonForm(s=>({...s,title:e.target.value}))} className={inputClass}/></Field><Field label="Description"><textarea rows={2} value={lessonForm.description} onChange={e=>setLessonForm(s=>({...s,description:e.target.value}))} className={inputClass}/></Field><div className="grid gap-3 sm:grid-cols-3"><Field label="Lesson type"><select value={lessonForm.lesson_type} onChange={e=>setLessonForm(s=>({...s,lesson_type:e.target.value}))} className={inputClass}>{['article','text','video','practice','quiz','assignment','project','mixed'].map(t=><option key={t} value={t}>{t}</option>)}</select></Field><Field label="Duration (minutes)"><input type="number" min="0" value={lessonForm.duration_minutes} onChange={e=>setLessonForm(s=>({...s,duration_minutes:e.target.value}))} className={inputClass}/></Field><Field label="Status"><select value={lessonForm.status} onChange={e=>setLessonForm(s=>({...s,status:e.target.value}))} className={inputClass}><option value="draft">Draft</option><option value="published">Published</option><option value="archived">Archived</option></select></Field></div><Field label="Lesson content"><textarea rows={8} value={lessonForm.content} onChange={e=>setLessonForm(s=>({...s,content:e.target.value}))} className={inputClass} placeholder="Write lesson notes, examples, instructions or practical work."/></Field></div><div className="mt-4 flex justify-end gap-2"><button type="button" onClick={()=>setShowLessonForm(false)} className="border border-white/10 px-4 py-2.5 text-xs text-slate-300">Cancel</button><button disabled={busy||!targetModule} className={buttonClass}>{busy?'Saving…':'Create lesson'}<Save size={14}/></button></div></form>
        :selectedLesson?<><form onSubmit={saveLesson} className="rounded-2xl border border-white/[.09] bg-[#0e1319] p-5"><div className="flex flex-wrap items-start justify-between gap-3"><div><p className="text-[10px] uppercase tracking-[.14em] text-[#f2d477]">Lesson editor</p><h2 className="mt-2 text-base font-semibold text-white">{selectedLesson.title}</h2><p className="mt-1 text-[10px] text-slate-500">{selectedLessonModule?.title||'Course module'}</p></div><Status value={selectedLesson.status}/></div><div className="mt-4 space-y-4"><Field label="Lesson title"><input required value={selectedLesson.title} onChange={e=>updateLesson({title:e.target.value})} className={inputClass}/></Field><Field label="Lesson description"><textarea rows={2} value={selectedLesson.description||''} onChange={e=>updateLesson({description:e.target.value})} className={inputClass}/></Field><div className="grid gap-3 sm:grid-cols-3"><Field label="Content type"><select value={selectedLesson.lesson_type||'article'} onChange={e=>updateLesson({lesson_type:e.target.value})} className={inputClass}>{['article','text','video','practice','quiz','assignment','project','mixed'].map(t=><option key={t} value={t}>{t}</option>)}</select></Field><Field label="Duration (minutes)"><input type="number" min="0" value={selectedLesson.duration_minutes||0} onChange={e=>updateLesson({duration_minutes:Number(e.target.value)})} className={inputClass}/></Field><Field label="Publication state"><select value={selectedLesson.status||'draft'} onChange={e=>updateLesson({status:e.target.value})} className={inputClass}><option value="draft">Draft</option><option value="published">Published</option><option value="archived">Archived</option></select></Field></div><Field label="Lesson content"><textarea rows={9} value={selectedLesson.content||''} onChange={e=>updateLesson({content:e.target.value})} className={inputClass} placeholder="Write lesson content, examples and instructions."/></Field></div><div className="mt-4 flex justify-end"><button disabled={busy} className={buttonClass}>{busy?'Saving…':'Save lesson'}<Save size={14}/></button></div></form>
          <section className="rounded-2xl border border-white/[.09] bg-[#0e1319] p-5"><div className="mb-4 flex items-center gap-2"><UploadCloud size={16} className="text-[#f2d477]"/><h3 className="text-sm font-semibold text-white">Learning resources</h3></div><form onSubmit={addResource} className="grid gap-3 sm:grid-cols-2"><Field label="Resource title"><input required value={resourceForm.title} onChange={e=>setResourceForm(s=>({...s,title:e.target.value}))} className={inputClass} placeholder="Dataset, worksheet or reading"/></Field><Field label="Resource URL"><input required type="url" value={resourceForm.external_url} onChange={e=>setResourceForm(s=>({...s,external_url:e.target.value}))} className={inputClass} placeholder="https://…"/></Field><Field label="Resource type"><select value={resourceForm.resource_type} onChange={e=>setResourceForm(s=>({...s,resource_type:e.target.value}))} className={inputClass}><option value="link">Link</option><option value="document">Document</option><option value="dataset">Dataset</option><option value="worksheet">Worksheet</option><option value="reading">Reading</option></select></Field><div className="flex items-end"><button disabled={busy} className={buttonClass}>Attach resource <Plus size={13}/></button></div></form>{resources.length?<div className="mt-3 space-y-2">{resources.map(r=><div key={r.id} className="flex items-center gap-3 rounded-lg border border-white/[.07] p-3"><FileText size={14} className="text-[#f2d477]"/><div className="min-w-0 flex-1"><p className="truncate text-xs text-slate-200">{r.title}</p><p className="truncate text-[10px] text-slate-500">{r.external_url||r.storage_path||r.resource_type}</p></div></div>)}</div>:<p className="mt-3 text-[10px] text-slate-500">No resources attached to this lesson yet.</p>}</section>
          <section className="rounded-2xl border border-white/[.09] bg-[#0e1319] p-5"><div className="mb-4 flex items-center gap-2"><Video size={16} className="text-[#f2d477]"/><h3 className="text-sm font-semibold text-white">Video metadata</h3></div><form onSubmit={addVideo} className="grid gap-3 sm:grid-cols-2"><Field label="Video title"><input required value={videoForm.title} onChange={e=>setVideoForm(s=>({...s,title:e.target.value}))} className={inputClass}/></Field><Field label="Provider"><select value={videoForm.provider} onChange={e=>setVideoForm(s=>({...s,provider:e.target.value}))} className={inputClass}>{['youtube','vimeo','mux','bunny','cloudflare','supabase','external','other'].map(p=><option key={p} value={p}>{p}</option>)}</select></Field><div className="sm:col-span-2"><Field label="External video ID"><input required value={videoForm.external_video_id} onChange={e=>setVideoForm(s=>({...s,external_video_id:e.target.value}))} className={inputClass} placeholder="YouTube ID or provider-specific ID"/></Field></div><div className="sm:col-span-2"><button disabled={busy} className={buttonClass}>Save video metadata <Plus size={13}/></button></div></form>{videos.length?<div className="mt-3 space-y-2">{videos.map(v=><div key={v.id} className="flex items-center gap-3 rounded-lg border border-white/[.07] p-3"><Video size={14} className="text-[#f2d477]"/><div className="min-w-0 flex-1"><p className="text-xs text-slate-200">{v.title||'Untitled video'}</p><p className="mt-1 text-[10px] text-slate-500">{v.provider||'Provider unavailable'} · {v.external_video_id||'No provider ID'}</p></div><Status value={v.status}/></div>)}</div>:<p className="mt-3 text-[10px] text-slate-500">No video metadata recorded for this lesson.</p>}<p className="mt-3 text-[10px] leading-5 text-slate-500">This saves metadata only. Actual file upload, provider readiness and playback depend on the configured media integration.</p></section></>:<Empty icon={FileText} title="Select or create a lesson" detail="Choose a lesson from the course structure or add a lesson to a module." action="Add a lesson" onAction={()=>{setShowLessonForm(true);setNewLessonModuleId(selectedLessonModule?.id||modules[0]?.id||'');}}/>}
      </section>
    </div>}
  </div>;

  const cohortsView = <div><Heading eyebrow="Programme delivery" title="Cohorts & learners" detail="View the cohorts in your organisation, inspect membership records, and start a new cohort when your permissions allow it." action="Create cohort" onAction={() => setShowCohortForm(true)}/>
    {!organisationId ? <Empty icon={UsersRound} title="Organisation context not available" detail="Cohort records are tenant-scoped. This account has no organisation ID in its current session context, so the page will not guess which learners it should display."/> : <>
      {showCohortForm && <form onSubmit={createCohort} className="mb-5 rounded-2xl border border-[#d7ad35]/25 bg-[#0e1319] p-5"><h2 className="text-sm font-semibold text-white">Create a cohort</h2><p className="mt-1 text-xs leading-5 text-slate-500">The backend enforces organisation scope, capacity and permissions.</p><div className="mt-4 grid gap-3 md:grid-cols-2"><Field label="Cohort name"><input required minLength={2} maxLength={150} value={cohortForm.name} onChange={e => setCohortForm(s => ({...s, name:e.target.value}))} className={inputClass}/></Field><Field label="Capacity (optional)"><input type="number" min="1" value={cohortForm.capacity} onChange={e => setCohortForm(s => ({...s, capacity:e.target.value}))} className={inputClass}/></Field><Field label="Start date"><input type="date" value={cohortForm.start_date} onChange={e => setCohortForm(s => ({...s, start_date:e.target.value}))} className={inputClass}/></Field><Field label="End date"><input type="date" min={cohortForm.start_date || undefined} value={cohortForm.end_date} onChange={e => setCohortForm(s => ({...s, end_date:e.target.value}))} className={inputClass}/></Field><div className="md:col-span-2"><Field label="Description"><textarea rows={2} value={cohortForm.description} onChange={e => setCohortForm(s => ({...s, description:e.target.value}))} className={inputClass}/></Field></div></div><div className="mt-4 flex justify-end gap-2"><button type="button" onClick={() => setShowCohortForm(false)} className="border border-white/10 px-4 py-2.5 text-xs text-slate-300">Cancel</button><button disabled={busy} className={buttonClass}>Create cohort <Plus size={13}/></button></div></form>}
      <div className="grid gap-5 xl:grid-cols-[minmax(0,.8fr)_minmax(0,1.2fr)]"><section className="rounded-2xl border border-white/[.09] bg-[#0e1319] p-4"><div className="mb-3 flex items-center justify-between"><h2 className="text-sm font-semibold text-white">Cohort records</h2><button onClick={() => void loadCohorts(token, organisationId)} className="text-xs text-[#f2d477]">Refresh</button></div>{cohorts.length ? <div className="space-y-2">{cohorts.map(cohort => <button key={cohort.id} onClick={() => setSelectedCohortId(cohort.id)} className={'w-full rounded-xl border p-4 text-left ' + (cohort.id === selectedCohortId ? 'border-[#d7ad35]/40 bg-[#d7ad35]/[.06]' : 'border-white/[.08] hover:border-white/20')}><div className="flex items-start justify-between gap-2"><span className="text-sm font-semibold text-slate-200">{cohort.name}</span><Status value={cohort.status}/></div><p className="mt-2 text-[10px] leading-5 text-slate-500">{cohort.start_date ? dateLabel(cohort.start_date) : 'Start date not set'}{cohort.end_date ? ' – ' + dateLabel(cohort.end_date) : ''}</p><p className="mt-1 text-[10px] text-slate-600">{cohort.capacity ? 'Capacity: ' + cohort.capacity : 'Capacity not specified'}</p></button>)}</div> : <p className="py-6 text-xs leading-5 text-slate-500">No cohorts were returned for this organisation. Create one if your role permits it, or ask the organisation administrator for access.</p>}</section>
      <section className="rounded-2xl border border-white/[.09] bg-[#0e1319] p-4 sm:p-5"><div className="flex items-center justify-between gap-3"><div><p className="text-[10px] uppercase tracking-[.14em] text-[#f2d477]">Selected cohort</p><h2 className="mt-2 text-base font-semibold text-white">{selectedCohort?.name || 'Select a cohort'}</h2></div>{selectedCohort && <Status value={selectedCohort.status}/>}</div>{selectedCohort ? cohortMembers.length ? <div className="mt-4 divide-y divide-white/[.07]">{cohortMembers.map((member, i) => <div key={member.id || member.user_id || i} className="flex items-center gap-3 py-3"><span className="grid size-9 place-items-center rounded-full bg-white/[.05] text-xs font-semibold text-[#f2d477]">{(member.name || member.full_name || member.email || 'L').charAt(0).toUpperCase()}</span><div className="min-w-0 flex-1"><p className="truncate text-xs font-semibold text-slate-200">{member.name || member.full_name || 'Cohort member'}</p><p className="mt-1 truncate text-[10px] text-slate-500">{member.email || member.user_id || 'Member identity not returned'}</p></div><Status value={member.status || member.role}/></div>)}</div> : <p className="mt-5 text-xs leading-5 text-slate-500">No member records were returned for this cohort, or the membership list is still loading.</p> : <p className="mt-5 text-xs leading-5 text-slate-500">Choose a cohort to inspect its actual membership records.</p>}</section></div>
    </>}
  </div>;

  const reviewView = <div><Heading eyebrow="Assessment and feedback" title="Learner review" detail="Review submissions, provide actionable feedback, and support demonstrated skill development."/><Empty icon={MessageSquareText} title="Submission review needs a backend endpoint" detail="The current backend exposes learner assignment submission, but no instructor-scoped list of submissions or grading/feedback write endpoint was found in the routes inspected for this task. I have not invented submissions or used an unsafe direct database read. Once permission-checked endpoints exist, this section can list pending work, show evidence, and save scores and feedback."/></div>;
  const aiView = <div><Heading eyebrow="AI-assisted teaching" title="AI teaching assistant" detail="Plan lessons, clarify learning outcomes, draft rubrics, and prepare teaching resources for human review."/><div className="grid gap-5 xl:grid-cols-[minmax(0,1fr)_300px]"><section className="rounded-2xl border border-white/[.09] bg-[#0e1319] p-5 sm:p-6"><div className="flex flex-wrap gap-2">{[{id:'instructor' as const,label:'Instructor support',detail:'Teaching plans and learner support'},{id:'content_generation' as const,label:'Content generation',detail:'Lesson and assessment drafts'}].map(m=><button key={m.id} onClick={()=>{setAiMode(m.id);setAiOutput('');}} className={'rounded-xl border px-4 py-3 text-left '+(aiMode===m.id?'border-[#d7ad35]/40 bg-[#d7ad35]/10':'border-white/10 bg-[#080b0f]')}><span className={'block text-xs font-semibold '+(aiMode===m.id?'text-[#f2d477]':'text-slate-200')}>{m.label}</span><span className="mt-1 block text-[10px] text-slate-500">{m.detail}</span></button>)}</div><form onSubmit={askAi} className="mt-5"><Field label="What are you preparing?"><textarea required rows={5} maxLength={12000} value={aiPrompt} onChange={e=>setAiPrompt(e.target.value)} className={inputClass} placeholder="Describe the topic, learner level, learning objective and output you need…"/></Field><div className="mt-3 flex flex-wrap items-center justify-between gap-3"><p className="max-w-lg text-[10px] leading-5 text-slate-500">AI output is a draft, not verified course content. Review accuracy, accessibility and assessment fairness before sharing.</p><button disabled={aiBusy||!aiPrompt.trim()} className={buttonClass}>{aiBusy?'Preparing…':'Generate draft'}<Send size={14}/></button></div></form>{aiOutput&&<div className="mt-5 rounded-xl border border-[#d7ad35]/20 bg-[#080b0f] p-4"><div className="mb-3 flex items-center justify-between gap-3"><h3 className="text-sm font-semibold text-white">Generated draft</h3><button type="button" onClick={()=>navigator.clipboard?.writeText(aiOutput)} className="text-xs text-[#f2d477]">Copy text</button></div><pre className="whitespace-pre-wrap break-words font-sans text-sm leading-6 text-slate-300">{aiOutput}</pre></div>}</section><aside className="h-fit rounded-2xl border border-white/[.09] bg-[#0e1319] p-5"><Sparkles size={20} className="text-[#f2d477]"/><h2 className="mt-3 text-sm font-semibold text-white">Useful starting prompts</h2><div className="mt-3 space-y-2">{['Create measurable learning outcomes for this topic.','Draft a lesson plan with examples and a short knowledge check.','Build a marking rubric that rewards reasoning and evidence.','Create differentiated practice for beginner and intermediate learners.','Review this assignment brief for ambiguity and accessibility.'].map(p=><button key={p} onClick={()=>setAiPrompt(p)} className="w-full rounded-lg border border-white/[.07] p-3 text-left text-xs leading-5 text-slate-300 hover:border-[#d7ad35]/30">{p}</button>)}</div></aside></div></div>;
  const creatorView = <div><Heading eyebrow="Independent creator tools" title="Creator studio" detail="Independent publishing and creator finance are separate from ordinary instructor access and depend on creator approval and payment infrastructure."/><div className="grid gap-4 md:grid-cols-2"><section className="rounded-2xl border border-white/[.09] bg-[#0e1319] p-6"><GraduationCap size={22} className="text-[#f2d477]"/><h2 className="mt-4 text-base font-semibold text-white">Creator approval and products</h2><p className="mt-2 text-sm leading-6 text-slate-400">The product document defines application, review, approval, product creation and publication. No creator-application status endpoint was found in the routes inspected for this page.</p><button onClick={()=>setTab('courses')} className="mt-5 inline-flex items-center gap-2 border border-white/10 px-4 py-2.5 text-xs font-semibold text-slate-200 hover:border-[#d7ad35]/40">Return to courses <ArrowRight size={14}/></button></section><section className="rounded-2xl border border-white/[.09] bg-[#0e1319] p-6"><Activity size={22} className="text-[#f2d477]"/><h2 className="mt-4 text-base font-semibold text-white">Earnings and payouts</h2><p className="mt-2 text-sm leading-6 text-slate-400">No creator earnings or payout API was found in the routes inspected. Sales and payout totals will not be fabricated; this needs authoritative transaction-backed endpoints.</p></section></div></div>;

  const activeLabel = nav.find(n=>n.id===tab)?.label||'Overview';
  const content: Record<Tab, ReactNode> = { overview, courses: courseList, curriculum, cohorts: cohortsView, review: reviewView, ai: aiView, creator: creatorView };
  const sidebar = <><div className="flex h-[76px] items-center gap-3 border-b border-white/[.08] px-5"><span className="grid size-10 place-items-center rounded-xl border border-[#d7ad35]/25 bg-[#d7ad35]/10 text-[#f2d477]"><GraduationCap size={21}/></span><div><p className="font-serif text-base text-white">Learnora <span className="text-[#f2d477]">ME</span></p><p className="mt-0.5 text-[9px] uppercase tracking-[.15em] text-slate-500">Instructor workspace</p></div></div><nav className="flex-1 overflow-y-auto px-3 py-5">{['Teaching','Tools'].map(group=><div key={group} className="mb-6"><p className="px-3 pb-2 text-[9px] font-bold uppercase tracking-[.15em] text-slate-600">{group}</p><div className="space-y-1">{nav.filter(n=>n.group===group).map(n=><button key={n.id} onClick={()=>{setTab(n.id);setMobileOpen(false);}} className={'flex w-full items-center gap-3 rounded-lg px-3 py-2.5 text-left text-xs font-medium transition '+(tab===n.id?'bg-[#d7ad35]/10 text-[#f2d477]':'text-slate-400 hover:bg-white/[.04] hover:text-white')}><n.icon size={16}/><span>{n.label}</span></button>)}</div></div>)}</nav><div className="border-t border-white/[.08] p-3"><div className="flex items-center gap-3 px-2 py-2"><span className="grid size-9 place-items-center rounded-full bg-white/[.06] text-xs font-semibold text-[#f2d477]">{(user.name||user.email||'I').charAt(0).toUpperCase()}</span><div className="min-w-0 flex-1"><p className="truncate text-xs font-semibold text-slate-200">{user.name||'Instructor'}</p><p className="truncate text-[10px] text-slate-600">{user.email||'Signed-in account'}</p></div><button aria-label="Log out" onClick={logout} className="p-2 text-slate-500 hover:text-white"><LogOut size={15}/></button></div></div></>;
  if (authLoading) return <div className="grid min-h-screen place-items-center bg-[#07090c] text-sm text-slate-400">Opening instructor workspace…</div>;
  return <div className="min-h-screen bg-[#07090c] text-slate-100">
    {mobileOpen&&<div className="fixed inset-0 z-50 lg:hidden"><button aria-label="Close navigation" onClick={()=>setMobileOpen(false)} className="absolute inset-0 bg-black/70"/><aside className="relative flex h-full w-[290px] flex-col border-r border-white/10 bg-[#0b0f14]">{sidebar}</aside></div>}
    <aside className="fixed inset-y-0 left-0 z-40 hidden w-[250px] flex-col border-r border-white/[.08] bg-[#0b0f14] lg:flex">{sidebar}</aside>
    <div className="min-w-0 lg:pl-[250px]"><header className="sticky top-0 z-30 border-b border-white/[.08] bg-[#07090c]/90 px-4 py-3 backdrop-blur-xl sm:px-6 lg:px-8"><div className="mx-auto flex max-w-[1500px] items-center gap-3"><button aria-label="Open navigation" onClick={()=>setMobileOpen(true)} className="rounded-lg border border-white/10 p-2 text-slate-300 lg:hidden"><Menu size={18}/></button><div className="min-w-0 flex-1"><p className="truncate text-sm font-semibold text-white">{activeLabel}</p><p className="mt-0.5 hidden text-[10px] text-slate-500 sm:block">Teach with intention. Help learners build evidence of what they can do.</p></div><button onClick={refresh} disabled={loading} className="inline-flex items-center gap-2 border border-white/10 px-3 py-2 text-[10px] text-slate-300 hover:border-[#d7ad35]/40 disabled:opacity-50"><RefreshCw size={13}/><span className="hidden sm:inline">{loading?'Refreshing…':'Refresh data'}</span></button><button onClick={()=>setTab('ai')} className="rounded-lg border border-white/10 p-2.5 text-[#f2d477]" aria-label="Open AI teaching assistant"><Sparkles size={16}/></button><button onClick={()=>setTab('courses')} className="flex items-center gap-2 rounded-lg border border-white/10 px-2 py-1.5"><span className="grid size-7 place-items-center rounded-md bg-[#d7ad35]/10 text-xs font-semibold text-[#f2d477]">{(user.name||user.email||'I').charAt(0).toUpperCase()}</span><ChevronDown size={13} className="text-slate-500"/></button></div></header>
      <main className="mx-auto max-w-[1500px] px-4 py-6 sm:px-6 lg:px-8 lg:py-8">{notice&&<div role={notice.kind==='error'?'alert':'status'} className={'mb-5 flex items-start gap-3 rounded-xl border px-4 py-3 text-sm '+(notice.kind==='error'?'border-red-400/20 bg-red-400/5 text-red-200':'border-emerald-400/20 bg-emerald-400/5 text-emerald-200')}><span>{notice.kind==='error'?<CircleAlert size={16}/>:<Check size={16}/>}</span><p className="flex-1">{notice.text}</p><button aria-label="Dismiss message" onClick={()=>setNotice(null)}><X size={14}/></button></div>}{content[tab]}</main>
      <footer className="border-t border-white/[.07] px-5 py-6 text-center text-[10px] text-slate-600">Learnora ME · Instructor workspace</footer>
    </div>
  </div>;
}
